root=Path(__file__).resolve().parents[1]
m=ast.parse((root/'tests/test_qs_grid_backend.py').read_text())
base=ast.parse((root/'tests/test_qs_grid_inspection.py').read_text())
sources=ast.literal_eval(next(n.value for n in base.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='sources' for t in n.targets)))
