with tempfile.TemporaryDirectory() as d:
 w=Path(d)
 for k,s in sources.items():p=w/k;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
 files=[str(p) for p in w.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/xposed/QsLayoutBackend.java')]
 subprocess.run(['java','com.sun.tools.javac.Main','-d',str(w),*files],check=True)
 subprocess.run(['java','-cp',str(w),'com.elitedarkkaiser.nubialy.xposed.LayoutTest'],check=True)
print('QS layout passed: native partition/order, label and sun-icon ownership, placement/touch bounds, current-stock restoration, excluded hosts and queued-stop fencing')
